<script setup lang="ts">
import { computed, ref } from 'vue'
import AppModal from '../../components/conservation/AppModal.vue'
import { conservationStore, speciesForPlant, type ThreatAlert } from '../../data/conservation'
const search=ref(''),severity=ref(''),status=ref(''),date=ref(''),location=ref(''),selected=ref<ThreatAlert|null>(null),note=ref('')
const cards=computed(()=>[['Active Alerts',conservationStore.alerts.filter(a=>a.status!=='Resolved').length],['High Severity',conservationStore.alerts.filter(a=>a.severity==='High').length],['Under Review',conservationStore.alerts.filter(a=>a.status==='Reviewing').length],['Resolved',conservationStore.alerts.filter(a=>a.status==='Resolved').length]])
const filtered=computed(()=>conservationStore.alerts.filter(a=>`${a.id} ${a.plantId} ${a.type}`.toLowerCase().includes(search.value.toLowerCase())&&(!severity.value||a.severity===severity.value)&&(!status.value||a.status===status.value)&&(!location.value||a.zone===location.value)&&(!date.value||a.detectedAt.includes(new Date(date.value+'T00:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})))))
function update(next:'Reviewing'|'Resolved'){if(!selected.value)return;if(note.value.trim())selected.value.notes.push(note.value.trim());selected.value.status=next;note.value=''}
</script>
<template><section class="page-intro"><div><p class="page-kicker">INCIDENT RESPONSE</p><h2>Threat Alerts</h2><p>Review environmental and security events around monitored plants.</p></div></section><section class="summary-grid"><article v-for="c in cards" :key="String(c[0])" class="summary-card"><p>{{c[0]}}</p><strong>{{c[1]}}</strong><small>Current alert register</small></article></section><div class="control-bar"><label class="field search-field"><span>Search</span><input v-model="search" placeholder="Alert ID, Plant ID or type" /></label><label class="field"><span>Severity</span><select v-model="severity"><option value="">All severities</option><option>Low</option><option>Medium</option><option>High</option></select></label><label class="field"><span>Status</span><select v-model="status"><option value="">All statuses</option><option>New</option><option>Reviewing</option><option>Resolved</option></select></label><label class="field"><span>Date</span><input v-model="date" type="date" /></label><label class="field"><span>Location</span><select v-model="location"><option value="">All locations</option><option>Zone A</option><option>Zone B</option><option>Zone C</option></select></label></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Alert ID</th><th>Alert Type</th><th>Plant ID</th><th>Species</th><th>Sensor</th><th>Location</th><th>Severity</th><th>Status</th><th>Detected At</th><th>Actions</th></tr></thead><tbody><tr v-for="a in filtered" :key="a.id"><td><strong>{{a.id}}</strong></td><td>{{a.type}}</td><td>{{a.plantId}}</td><td><em>{{speciesForPlant(a.plantId)?.scientificName}}</em></td><td>{{a.sensorId}}</td><td>{{a.zone}}</td><td><span class="badge" :class="a.severity.toLowerCase()">{{a.severity}}</span></td><td><span class="badge" :class="a.status.toLowerCase()">{{a.status}}</span></td><td>{{a.detectedAt}}</td><td><div class="action-group"><button class="action-button" @click="selected=a">View</button><button v-if="a.status==='New'" class="action-button" @click="selected=a;update('Reviewing')">Review</button><button v-if="a.status!=='Resolved'" class="action-button" @click="selected=a">Resolve</button><RouterLink class="action-button" :to="{name:'conservation-observations',query:{plant:a.plantId}}">Plant</RouterLink><RouterLink class="action-button" :to="{name:'conservation-map',query:{plant:a.plantId}}">Location</RouterLink></div></td></tr></tbody></table></div></section><AppModal v-if="selected" :title="`${selected.id} · ${selected.type}`" :subtitle="`${selected.plantId} · ${speciesForPlant(selected.plantId)?.scientificName}`" @close="selected=null"><dl class="detail-list"><div><dt>Sensor / Device</dt><dd>{{selected.sensorId}}</dd></div><div><dt>Environmental Reading</dt><dd>{{selected.reading}}</dd></div><div><dt>Timestamp</dt><dd>{{selected.detectedAt}}</dd></div><div><dt>Location</dt><dd>{{selected.zone}}</dd></div><div><dt>Severity</dt><dd>{{selected.severity}}</dd></div><div><dt>Current Status</dt><dd>{{selected.status}}</dd></div></dl><h3>Response History</h3><div v-if="!selected.notes.length" class="media-placeholder">No response notes yet</div><p v-for="n in selected.notes" :key="n" class="response-note">{{n}}</p><label class="form-field"><span>Add response note</span><textarea v-model="note" placeholder="Describe the response or investigation"></textarea></label><div class="modal-actions"><button v-if="selected.status==='New'" class="secondary-button" @click="update('Reviewing')">Mark as Reviewing</button><button v-if="selected.status!=='Resolved'" class="primary-button" @click="update('Resolved')">Mark as Resolved</button></div></AppModal></template>
<style scoped>a.action-button{text-decoration:none}.response-note{padding:10px;border-left:3px solid #65a187;background:#f4f8f4;color:#526b60;font-size:10px}</style>
